contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address programOperator, address ownedBy, bytes calldata encodedParameters) public {
        vm.assume(programOperator != address(0) && ownedBy != address(0));

        // Need to deploy a mock IRoundImplementation and set initial owner
        // To simplify, we set programOperator as the caller and also as the one who initializes and calls create
        vm.startPrank(programOperator);
        c.initialize();
        c.updateRoundImplementation(payable(address(0x1234))); // dummy address, but we need a real contract
        // Actually we need a real contract that implements initialize. For simplicity, we use a mock.
        // But to keep test self-contained, we assume a proper setup

        // Since we cannot deploy a real clone, we just check that the rule holds for the reference.
        // For the buggy version, the assertion will fail.

        // Here we just test that owner() returns the same after initialization
        // The rule: after initialization, owner() returns the new owner, not msg.sender
        // We'll just call the initializer and check that owner() returns the initial owner

        c.initialize();
        address initialOwner = c.owner();

        // For a clone created by create(), the clone's owner() should be the ownedBy parameter
        // But we cannot test that without a proper implementation. So we focus on the 
        // contract being tested (C) itself.

        // Actually the bug is in C's owner() function, so we test that directly.
        // The rule: after ownership transfer, owner() returns the new owner, not msg.sender

