pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner, bytes calldata encodedParameters, address ownedBy) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // Set up program operator to allow create
        vm.prank(address(this));
        c.initialize();
        vm.store(address(c), bytes32(uint256(keccak256(abi.encode(address(0), uint256(1))))), bytes32(uint256(1))); // Hack: set programOperators[caller] true via storage; alternative: use a dedicated mapping setter but C has none. So we prank caller as owner to add program operator.
        vm.prank(address(this));
        // Make the contract's owner (address(this)) add caller as program operator
        // But C doesn't have addProgramOperator. So we assume caller is the owner for simplicity.
        // Instead, we use a cheat to set programOperators[caller] directly:
        bytes32 slot = keccak256(abi.encode(caller, uint256(1))); // mapping slot = keccak256(abi.encode(key, slot))
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Now drive create
        vm.prank(caller);
        address roundAddr = c.create(encodedParameters, ownedBy);

        // After create, the contract C's owner is address(this). Try to call transferOwnership from owner.
        // In reference C, require(newOwner != address(0)) will pass for non-zero newOwner.
        // In mutant, require(newOwner == address(0)) will revert.
        vm.prank(address(this));
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Reference: never reverts for non-zero newOwner. Mutant: always reverts.
        assertTrue(!reverted, "transferOwnership should not revert for non-zero newOwner");
    }
}

